contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 d) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d)); require(d <= 1000000000000000000000000000000);
        require(d > 0);
        require(address(this).balance >= d);

        c.deposit{value: d}(); if (__ESBMC_reverted()) return;
        uint256 balanceAfterDeposit = address(c).balance;

        bool withdrawDPlusOneReverted;
        c.withdraw(d + 1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrawDPlusOneReverted = true;
        } else {
            withdrawDPlusOneReverted = false;
        }

        uint256 balanceAfterFailedWithdraw = address(c).balance;

        bool withdrawDReverted;
        c.withdraw(d); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            withdrawDReverted = true;
        } else {
            withdrawDReverted = false;
        }

        assert(
            withdrawDPlusOneReverted &&
            balanceAfterFailedWithdraw == balanceAfterDeposit &&
            !withdrawDReverted
        );
    }

    receive() external payable {}
}

