// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 d) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(d > 0);
        vm.assume(address(this).balance >= d);
        try c.deposit{value: d}() {} catch { return; }
        uint256 balanceAfterDeposit = address(c).balance;
        bool withdrawDPlusOneReverted;
        try c.withdraw(d + 1) {
            withdrawDPlusOneReverted = false;
        } catch {
            withdrawDPlusOneReverted = true;
        }
        uint256 balanceAfterFailedWithdraw = address(c).balance;
        bool withdrawDReverted;
        try c.withdraw(d) {
            withdrawDReverted = false;
        } catch {
            withdrawDReverted = true;
        }
        assertTrue(withdrawDPlusOneReverted &&
            balanceAfterFailedWithdraw == balanceAfterDeposit &&
            !withdrawDReverted);
    }

    function testFuzz_run(uint256 d) public {
        _run(d);
    }

    receive() external payable {}
}
